def transform(wb):
    ws = wb['imported Data']
    max_row = ws.max_row
    if max_row is None:
        return
    max_col = ws.max_column
    if max_col is None or max_col < 3:
        max_col = 3
    for r in range(max_row, 0, -1):
        row_blank = True
        for c in range(1, max_col + 1):
            cv = ws.cell(row=r, column=c).value
            if cv is not None and not (cv == str(cv) and cv.strip() == ''):
                row_blank = False
                break
        if row_blank:
            ws.delete_rows(r, 1)
            continue
        v = ws.cell(row=r, column=3).value
        if v is not None and v is not True and v is not False and v != str(v):
            if v >= -1 and v <= 1:
                ws.delete_rows(r, 1)
